import re

# Name of the file to patch
FILENAME = "srvwww_svc.c"

# Fragment to be inserted after the last `#include`,
# where the global variable `documentroot` is declared
global_patch = r"""

// Include added to use the folder_exists function
#include "util.h"

/***** ADDED GLOBAL VARIABLE ******/
char *documentroot;
"""

# Fragment to be inserted inside `main()`, at the beginning,
# before `svcudp_create` or `svctcp_create`
main_patch = r"""
    // Added to the code generated by rpcgen
    /****************************************************************************** */
       if (argc < 2)
       {
         fprintf(stderr, "Usage: %s absolute_document_root_path \n", argv[0]);
         exit(1);
       }
       documentroot = strdup(argv[1]);
       if (documentroot == NULL)
       {
          fprintf(stderr, "Error: Could not allocate memory to store the document root folder name\n");
          exit(12);
       }
       if (documentroot[strlen(documentroot)-1] == '/') documentroot[strlen(documentroot)-1] = 0;
       if (!folder_exists(documentroot))
       {
          fprintf(stderr, "Error: Folder %s does not exist or is not a directory\n", documentroot);
          exit(13);
       }
       fprintf(stderr, "Server: Document root is: %s\n", documentroot);
    /******************************************************************************/
"""

# Read the original file
with open(FILENAME, "r") as f:
    lines = f.readlines()

# Insert `global_patch` after the last `#include`
insert_index = 0
for i, line in enumerate(lines):
    if line.startswith("#include"):
        insert_index = i + 1  # Right after the last #include

# Avoid inserting multiple times
if global_patch not in "".join(lines):
    lines.insert(insert_index, global_patch + "\n")
else:
    print(
        f"The file {FILENAME} has already been modified previously. No changes needed."
    )
    exit()

# Insert `main_patch` inside `main()`,
# before the first call to `svcudp_create` or `svctcp_create`
inside_main = False
for i, line in enumerate(lines):
    if re.search(r"main *\(", line):  # Detect start of main()
        inside_main = True

    if inside_main and re.search(
        r"\bsvc(udp|tcp)_create\b", line
    ):  # Find first occurrence
        lines.insert(i, main_patch + "\n")
        break  # Insert only once

# Save the modified file
with open(FILENAME, "w") as f:
    f.writelines(lines)

print(f"Modifications applied to {FILENAME}")
